#!/usr/bin/env bash

# Encode the validation data generated by generate_llava70b_dataset_text.py.
# The generated-data switch is intentionally enabled in this dedicated script.

set -euo pipefail

cd "$(dirname "$0")/.."

PROMPT_TYPE="${PROMPT_TYPE:-prompt_5}"
DATASET_SPLIT="val"
BASE_MODEL="${BASE_MODEL:-llava-hf-llava-v1.6-mistral-7b-hf}"
TASK_TYPE="${TASK_TYPE:-ir}"
USE_GENERATED_VALIDATION_DATA=true
USE_LLAVA_NEXT_TRAINING_PROMPTS="${USE_LLAVA_NEXT_TRAINING_PROMPTS:-false}"

LLAVA_NEXT_PROMPT_ARGS=()
case "${USE_LLAVA_NEXT_TRAINING_PROMPTS,,}" in
    true|1|yes)
        LLAVA_NEXT_PROMPT_ARGS+=(--use_llava_next_training_prompts)
        DEFAULT_GENERATED_VALIDATION_DATA_ROOT="./generated_llava70b_data_llava_next_training"
        ;;
    false|0|no|"")
        DEFAULT_GENERATED_VALIDATION_DATA_ROOT="./generated_llava70b_data"
        ;;
    *)
        echo "USE_LLAVA_NEXT_TRAINING_PROMPTS must be true or false." >&2
        exit 2
        ;;
esac

GENERATED_VALIDATION_DATA_ROOT="${GENERATED_VALIDATION_DATA_ROOT:-${DEFAULT_GENERATED_VALIDATION_DATA_ROOT}}"

GENERATED_VALIDATION_ARGS=(
    --use_generated_validation_data
    --generated_validation_data_root "${GENERATED_VALIDATION_DATA_ROOT}"
    "${LLAVA_NEXT_PROMPT_ARGS[@]}"
)

if [[ "${PROMPT_TYPE}" == "prompt_random_5" ]]; then
    # random_token_views.sh encodes both val and test.  Its val encoding uses
    # the generated files, while its test encoding remains on the original data.
    export PROMPT_TYPE USE_GENERATED_VALIDATION_DATA GENERATED_VALIDATION_DATA_ROOT
    bash "$(dirname "$0")/random_token_views.sh" encode
else
    GPUS="${GPUS:-4}"
    NUM_NODES="${NUM_NODES:-1}"

    deepspeed --num_gpus="${GPUS}" --num_nodes="${NUM_NODES}" src/encode.py \
        --model_name_or_path "./checkpoints/${BASE_MODEL}" \
        --output_dir ./output \
        --fp16 \
        --dataset_name "${DATASET:-flickr}" \
        --task_type "${TASK_TYPE}" \
        --encode_type "${ENCODE_TYPE:-image}" \
        --per_device_batch_size "${PER_DEVICE_BATCH_SIZE:-1}" \
        --dataset_split "${DATASET_SPLIT}" \
        --reps_loc "${REPS_LOC:-after_pad}" \
        --num_expended_tokens "${EXPENDED_TOKENS:-0}" \
        --eol_type "${EOL_TYPE:-disassembleeol_separate}" \
        --sparse_value_type "${SPARSE_VALUE_TYPE:-sum}" \
        --sparse_lower_or_upper "${SPARSE_LOWER_OR_UPPER:-lower}" \
        --calculate_type "${CALCULATE_TYPE:-concat}" \
        --prompt_type "${PROMPT_TYPE}" \
        --sparse_length "${SPARSE_LENGTH:-40}" \
        "${GENERATED_VALIDATION_ARGS[@]}"
fi
